// int8 1D-CNN fall classifier (weights in include/cnn_fall_model.h, generated by
// tools/ai_lab/export_final.py). Bit-exact mirror of tools/ai_lab/quant.py::int8_forward.
//
// Input : 100 samples x [ax, ay, az, gx, gy, gz] (gravity-removed linear accel in
//         m/s^2, gyro in rad/s), row-major [sample][6]. A 7th channel |a| is added here.
// Layers: conv(7->C1,k5,s2) -> conv(C1->C2,k5,s2) -> conv(C2->C3,k3,s1), ReLU after each,
//         global max + mean over time, dense -> sigmoid.
#include "ai_cnn.h"

#if ENABLE_CNN_AI

#include <math.h>
#include <stdint.h>
#include "cnn_fall_model.h"

static int8_t cnnX0[CNN_T * CNN_IN_CH];
static int8_t cnnA1[CNN_T1 * CNN_C1];
static int8_t cnnA2[CNN_T2 * CNN_C2];
static int8_t cnnA3[CNN_T3 * CNN_C3];

static inline int8_t clampQ(int v, int lo, int hi) {
  return (int8_t)(v < lo ? lo : (v > hi ? hi : v));
}

static void convLayer(const int8_t *in, int tIn, int cIn, int8_t *out, int tOut, int cOut,
                      int k, int stride, int pad, const int8_t *W, const int32_t *B,
                      const float *M) {
  for (int t = 0; t < tOut; ++t) {
    const int base = t * stride - pad;
    for (int o = 0; o < cOut; ++o) {
      int32_t acc = B[o];
      const int8_t *w = W + (size_t)o * k * cIn;
      for (int kk = 0; kk < k; ++kk) {
        const int ti = base + kk;
        if (ti < 0 || ti >= tIn) continue;
        const int8_t *xi = in + (size_t)ti * cIn;
        const int8_t *wk = w + (size_t)kk * cIn;
        for (int ci = 0; ci < cIn; ++ci) acc += (int32_t)wk[ci] * (int32_t)xi[ci];
      }
      const float y = (float)acc * M[o];
      out[(size_t)t * cOut + o] = clampQ((int)lroundf(y), 0, 127);  // ReLU + requantise
    }
  }
}

float cnnEnsembleThreshold() { return AI_ENSEMBLE_THRESHOLD; }

float cnnInfer(const float *win) {
  for (int t = 0; t < CNN_T; ++t) {
    const float *s = win + t * 6;
    float v[CNN_IN_CH];
    for (int c = 0; c < 6; ++c) v[c] = s[c];
    v[6] = sqrtf(s[0] * s[0] + s[1] * s[1] + s[2] * s[2]);
    for (int c = 0; c < CNN_IN_CH; ++c) {
      cnnX0[t * CNN_IN_CH + c] = clampQ((int)lroundf((v[c] - CNN_IN_MEAN[c]) * CNN_IN_INV[c]), -127, 127);
    }
  }
  convLayer(cnnX0, CNN_T, CNN_IN_CH, cnnA1, CNN_T1, CNN_C1, 5, 2, 2, CNN_W1, CNN_B1, CNN_M1);
  convLayer(cnnA1, CNN_T1, CNN_C1, cnnA2, CNN_T2, CNN_C2, 5, 2, 2, CNN_W2, CNN_B2, CNN_M2);
  convLayer(cnnA2, CNN_T2, CNN_C2, cnnA3, CNN_T3, CNN_C3, 3, 1, 1, CNN_W3, CNN_B3, CNN_M3);

  float z = CNN_FCB;
  for (int c = 0; c < CNN_C3; ++c) {
    int mx = 0;
    int32_t sum = 0;
    for (int t = 0; t < CNN_T3; ++t) {
      const int v = cnnA3[t * CNN_C3 + c];
      if (v > mx) mx = v;
      sum += v;
    }
    z += (float)mx * CNN_S_LAST * CNN_FCW[c];
    z += ((float)sum / (float)CNN_T3) * CNN_S_LAST * CNN_FCW[CNN_C3 + c];
  }
  if (!isfinite(z)) return 0.0f;
  return z >= 0.0f ? 1.0f / (1.0f + expf(-z)) : expf(z) / (1.0f + expf(z));
}

#endif  // ENABLE_CNN_AI
